// Token verification and minting (PRO-009, PRO-010, PRO-011; BE-012, BE-013; 05 §3.1, §3.2):
// claims, lifetimes, skew, the algorithm allow-list, key selection by tenant, and the per-tenant
// surrogates. Every key here is generated by the test.
import { createHmac, randomUUID } from 'node:crypto';
import { uuid7 } from '@docedit/model';
import { beforeEach, describe, expect, it } from 'vitest';
import { b64url, signJws } from '../../src/control-plane/jwt.ts';
import { MemoryTenantRegistry } from '../../src/control-plane/tenants.ts';
import { signingKey, TokenService } from '../../src/control-plane/tokens.ts';
import { MemoryUserDirectory } from '../../src/control-plane/users.ts';
import { hostKey } from './support.ts';

const SERVICE = 'https://docs.example.test';

describe('user tokens (PRO-009, PRO-010)', () => {
  let now = Date.now();
  let tenant: string;
  let registry: MemoryTenantRegistry;
  let users: MemoryUserDirectory;
  let tokens: TokenService;
  const host = hostKey('ES256');
  const doc = uuid7();

  beforeEach(async () => {
    now = Date.now();
    tenant = randomUUID();
    registry = new MemoryTenantRegistry(() => now);
    users = new MemoryUserDirectory();
    await registry.putTenant(tenant, 't');
    await registry.addKey(tenant, { kid: host.kid, use: 'user', alg: 'ES256', jwk: host.jwk });
    tokens = new TokenService({
      registry,
      users,
      serviceId: SERVICE,
      signing: signingKey(undefined, 'svc'),
      now: () => now,
    });
  });

  const sign = (
    claims: Record<string, unknown> = {},
    header: Record<string, unknown> = {},
    key = host,
  ) => {
    const iat = Math.floor(now / 1000);
    return signJws(
      { alg: key.alg, typ: 'JWT', kid: key.kid, ...header },
      {
        iss: 'host',
        aud: SERVICE,
        iat,
        exp: iat + 300,
        jti: uuid7(),
        tid: tenant,
        sub: 'u-1',
        docs: { [doc]: 'editor' },
        ...claims,
      },
      key.privateKey,
    );
  };
  const refused = async (token: string, code = 'unauthenticated') =>
    expect(tokens.verifyUser(token)).rejects.toMatchObject({ code });

  it('accepts the claims of 05 §3.1 and reads the document role, name and groups (PRO-009 criterion 1)', async () => {
    const id = await tokens.verifyUser(
      sign({ name: 'Una', grp: ['legal', 'eu'], restrict: ['no-export'] }),
    );
    expect(id).toMatchObject({
      tenant,
      doc,
      docs: { [doc]: 'editor' },
      sub: 'u-1',
      name: 'Una',
      restrict: ['no-export'],
    });
    expect(id.connection).toMatchObject({
      role: 'editor',
      groups: ['legal', 'eu'],
      participantRoles: [],
    });
    for (const role of ['viewer', 'commenter', 'suggester', 'editor', 'owner', 'filler'])
      expect((await tokens.verifyUser(sign({ docs: { [doc]: role } }))).docs[doc]).toBe(role);
    await refused(sign({ docs: { [doc]: 'admin' } }));
    await refused(sign({ docs: {} }));
  });

  it('accepts aud only when it equals the service identifier exactly (criterion 2)', async () => {
    for (const aud of [`${SERVICE}/`, SERVICE.toUpperCase(), 'https://docs.example', [SERVICE]])
      await refused(sign({ aud }));
    await expect(tokens.verifyUser(sign({ aud: SERVICE }))).resolves.toBeTruthy();
  });

  it('allows a lifetime of 15 minutes and not a second more (criterion 3)', async () => {
    const iat = Math.floor(now / 1000);
    await expect(tokens.verifyUser(sign({ iat, exp: iat + 900 }))).resolves.toBeTruthy();
    await refused(sign({ iat, exp: iat + 901 }));
  });

  it('allows 60 seconds of skew on exp and iat (criterion 4)', async () => {
    const t = Math.floor(now / 1000);
    await expect(tokens.verifyUser(sign({ iat: t - 300, exp: t - 59 }))).resolves.toBeTruthy();
    await refused(sign({ iat: t - 300, exp: t - 61 }), 'token_expired');
    await expect(tokens.verifyUser(sign({ iat: t + 59, exp: t + 300 }))).resolves.toBeTruthy();
    await refused(sign({ iat: t + 61, exp: t + 300 }));
  });

  it('accepts 20 documents in docs and refuses 21 (criterion 5)', async () => {
    const docs = (n: number) =>
      Object.fromEntries(Array.from({ length: n }, () => [uuid7(), 'viewer']));
    expect(Object.keys((await tokens.verifyUser(sign({ docs: docs(20) }))).docs)).toHaveLength(20);
    await refused(sign({ docs: docs(21) }));
  });

  it('selects keys by tid from the registration and never from the token (PRO-010 criteria 1, 3)', async () => {
    const intruder = hostKey('ES256');
    // An embedded key, a key URL or a certificate URL is not read: the signature must match a registered key.
    const pub = intruder.jwk;
    await refused(
      sign(
        {},
        { jwk: pub, jku: 'https://evil.example/jwks', x5u: 'https://evil.example/c' },
        intruder,
      ),
    );
    // Another tenant's key does not verify this tenant's tokens.
    const other = randomUUID();
    await registry.putTenant(other, 'o');
    await registry.addKey(other, {
      kid: intruder.kid,
      use: 'user',
      alg: 'ES256',
      jwk: intruder.jwk,
    });
    await refused(sign({ tid: tenant }, {}, intruder));
    await expect(tokens.verifyUser(sign({ tid: other }, {}, intruder))).resolves.toMatchObject({
      tenant: other,
    });
    // An unregistered tid is refused.
    await refused(sign({ tid: randomUUID() }));
  });

  it('accepts ES256, EdDSA and RS256, and refuses none, HMAC and an algorithm the key is not for (PRO-010 criterion 2)', async () => {
    for (const alg of ['EdDSA', 'RS256'] as const) {
      const k = hostKey(alg);
      await registry.addKey(tenant, { kid: k.kid, use: 'user', alg, jwk: k.jwk });
      await expect(tokens.verifyUser(sign({}, {}, k))).resolves.toBeTruthy();
    }
    const header = (h: object) => b64url(JSON.stringify(h));
    const payload = b64url(
      JSON.stringify({
        iss: 'h',
        aud: SERVICE,
        iat: Math.floor(now / 1000),
        exp: Math.floor(now / 1000) + 60,
        jti: 'j',
        tid: tenant,
        sub: 's',
        docs: { [doc]: 'owner' },
      }),
    );
    await refused(`${header({ alg: 'none', typ: 'JWT' })}.${payload}.`);
    // HS256 with the public key as the secret (algorithm confusion).
    const hsInput = `${header({ alg: 'HS256', typ: 'JWT', kid: host.kid })}.${payload}`;
    const mac = createHmac('sha256', JSON.stringify(host.jwk)).update(hsInput).digest('base64url');
    await refused(`${hsInput}.${mac}`);
    // An ES256 key never checks an RS256 token, whatever the header says.
    const rsa = hostKey('RS256', host.kid);
    await refused(sign({}, { alg: 'RS256' }, rsa));
    await refused(sign({}, { crit: ['exp'] }));
  });

  it('does not take a service credential as a user token (05 §3.2)', async () => {
    await refused(sign({}, { typ: 'dep-svc+jwt' }));
  });

  it('maps each sub to a per-tenant surrogate, created once, unrelated across tenants (BE-013 criteria 1, 2, 3, 5)', async () => {
    const a = await tokens.verifyUser(sign({ sub: 'same', name: 'Sam' }));
    const again = await tokens.verifyUser(sign({ sub: 'same' }));
    expect(a.connection.sub).toBe(again.connection.sub);
    expect(a.connection.sub).not.toBe('same');
    expect(await users.displayName(tenant, 'same')).toBe('Sam');
    const other = randomUUID();
    await registry.putTenant(other, 'o');
    await registry.addKey(other, { kid: host.kid, use: 'user', alg: 'ES256', jwk: host.jwk });
    const b = await tokens.verifyUser(sign({ sub: 'same', tid: other }));
    expect(b.connection.sub).not.toBe(a.connection.sub);
    // The name can be purged alone; erasing deletes the mapping, and nothing resolves the surrogate.
    expect(await users.purgeName(tenant, 'same')).toBe(true);
    expect(await users.displayName(tenant, 'same')).toBeNull();
    expect(await users.erase(tenant, 'same')).toBe(true);
    expect(await users.subsOf(tenant, [a.connection.sub])).toEqual(new Map());
    // A token of the erased user gets a new surrogate, unrelated to the old one.
    expect((await tokens.verifyUser(sign({ sub: 'same' }))).connection.sub).not.toBe(
      a.connection.sub,
    );
  });

  it('mints tokens that pass its own verification and carry what the host asked for (PRO-011 criterion 1; D60)', async () => {
    const minted = await tokens.mint(tenant, {
      sub: 'm-1',
      docs: { [doc]: 'owner' },
      grp: ['g'],
      name: 'M',
    });
    const id = await tokens.verifyUser(minted.token);
    expect(id).toMatchObject({ tenant, sub: 'm-1', docs: { [doc]: 'owner' }, name: 'M' });
    expect(id.expiresAt - id.issuedAt).toBe(900_000);
    // Another tenant cannot use a token minted for this one.
    const forged = minted.token.split('.');
    const p = JSON.parse(Buffer.from(forged[1]!, 'base64url').toString());
    p.tid = randomUUID();
    await refused(`${forged[0]}.${b64url(JSON.stringify(p))}.${forged[2]}`);
  });
});
